    "purpose": "İşletmelerin finansal tablolarının ve dönem içi kayıtlarının doğruluğunun araştırılması, muhasebeleştirme işlemlerinin güvenilirliğini bozacak olası hata, hile ve eksikliklerin belirlenerek düzeltilmesinin sağlanmasıdır.",
    "content": "Denetim işlevi, muhasebe mesleği, bağımsız denetimde meslek ahlakı , genel kabul görmüş denetim standartları, denetim amaçları, denetim süreci, denetim sürecinde önemlilik ve risk, denetim raporları, hileli finansal raporlama ve denetçilerin sorumluluğu, denetim kanıtları ve prosedürleri, çalışma kağıtları, iç kontrol sistemi, nakit sisteminin denetimi, alacakların denetimi, stokların denetimi, duran varlıkların denetimi, yabancı kaynakların denetimi, özkaynakların denetimi, gelir tablosunun denetimi ve vaka analizleri.",
    "methods": "Teorik anlatım, uygulama, soru–cevap, tartışma.",
