    "purpose": "Bu dersin amacı; vergi hukukunun kaynağını oluşturan vergilendirmenin anayasal dayanaklarının ve idari prensiplerinin detaylı analizi ve vergi uyuşmazlıkları ve çözümlerinin ele alınarak vergi hukuku kapsamında vergi kabahat ve suçlarının incelenmesidir.",
    "content": "Vergi hukukunun konusu ve temel kaynakları. Vergi kanunlarının uygulanması, verginin tarafları, konusu, vergiyi doğuran olay. Vergi matrahı, verginin tarh ve tahakkuku. Vergi alacağının ortadan kalkması. Vergi hukukunda süreler, vergi idaresinin örgütlenmesi, vergi suç ve cezaları. Vergi uyuşmazlıkları ve vergi yargısı",
    "methods": "Teorik anlatım, uygulama, soru–cevap, tartışma.",
    "resources": "Dersin gerçek OBS kaynakları; güncel muhasebe ve finans literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
