    "purpose": "sermaye piyasalarının yapısını, işleyişini ve yatırım araçlarını analitik bir bakış açısıyla inceleyerek, öğrencilerin finansal varlıkların fiyatlanması, portföy yönetimi, piyasa etkinliği, risk analizi ve davranışsal finans kavramlarını derinlemesine anlamaları amaçlanmaktadır.",
    "content": "Sermaye piyasalarının işleyişi, finansal araçlar ve piyasalar, hisse senedi ve tahvil fiyatlaması, portföy teorileri, risk-getiri analizi, piyasa etkinliği, arbitraj ve fiyatlama modelleri (CAPM, APT), davranışsal finans, türev ürünlerin analizi, algoritmik işlem ve piyasa mikro yapısı, uluslararası sermaye akımları ve finansal krizlerin sermaye piyasalarına etkisi.",
