    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "purpose": "İşletmelerin rekabet avantajı elde edebilmeleri için gerekli olan etkin bir Finans yönetiminin gerçekleşebilmesi için yapılması gerekenlerin öğrenciye kazandırılması.",
    "content": "Yatırım ve finansman stratejilerinin belirlenmesi ve koordinasyonu. Tahminler, satış tahmini, üretim ve satınalma tahminleri, makro ekonomiği kapsayan tahminler ve bunların sonucunda sağlanan proforma bilanço ve gelir tablosu ve nakit bütçesi, Paranın Zaman Değeri. Basit faiz, bileşik faiz, nominal ve efektif faiz, annuiteler, eşit taksitli ödemelerin bugünkü değeri.",
    "methods": "Teorik anlatım, uygulama, soru–cevap, tartışma.",
    "resources": "Dersin gerçek OBS kaynakları; güncel muhasebe ve finans literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
