    "purpose": "Bu dersin amacı, öğrencilerin maliyet muhasebesi alanında ileri düzey bilgi ve beceriler kazanmasını sağlamaktır. Öğrenciler, modern maliyetleme yaklaşımlarını analiz edebilecek, stratejik karar alma süreçlerinde maliyet bilgilerinden etkin biçimde yararlanabilecek ve güncel teknolojik gelişmelerin maliyet muhasebesine etkilerini değerlendirebilecektir.",
    "content": "Gelişmiş maliyet sistemleri, faaliyet tabanlı maliyetleme, hedef maliyetleme, yaşam döngüsü maliyetleme, kalite maliyetleri, çevresel maliyet muhasebesi, stratejik maliyet yönetimi, rekabet avantajı analizi, maliyet kontrolü ve performans ölçümü, dijitalleşme ve yapay zekâ destekli maliyet uygulamaları.",
    "methods": "Anlatım, Alıştırma & Problem Çözme, Soru & Cevap",
    "resources": "Dersin gerçek OBS kaynakları; güncel muhasebe ve finans literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
