    "term": "Bahar",
    "purpose": "Bu dersin amacı; faiz, kur ve fiyat değişimlerinden kaynaklanan finansal risklerin yönetilmesi için gereken finansal risk yönetim tekniklerinin ve araçlarının teorik ve uygulamalı olarak öğretilmesidir.",
    "content": "Finansal Risk Teorisi, Riskin Ölçümü ve Değerlemesi, Finansal Futures İle Hedging ve Spekülasyon, Döviz, Faiz ve Endeks Futures, Forward Kontratlar, Opsiyon Piyasalar, Opsiyon Değerleme Modelleri, Swap Türleri ve Swapların Fiyatlandırılması, İleri Türev Piyasa Stratejileri",
