    "content": "Fark denklemleri, Gecikme işlemcileri, Durağan ARMA Süreci,Öngörü,Maksimum likelihood yöntemi,Spektral analiz,asimtotik dağılım teorisi,doğrusal regresyon modelleri,eşanlı denklemler,vektör otoregresif modelleri,doğrusal olmayan zaman serileri,birim kök testleri,eş bütünleşme,zaman serisi modellerinde değişen varyans",
